-- Real PostgreSQL accounting/permissions; no physical file transfer claimed.
begin;
-- Synthetic metadata-only tests use the same transaction-local permission as
-- Storage's own database tests. The application never bypasses Storage API.
set local storage.allow_delete_query='true';
select extensions.plan(52);
create temporary table quota_fixture(a uuid,b uuid,c uuid,actor uuid,patient uuid,file_id uuid,path text);
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); patient uuid:=gen_random_uuid(); f record;
begin
  insert into auth.users(id,email) values(actor,actor||'@example.test');
  insert into public.businesses(id,name,slug,industry) values(a,'Synthetic quota A',a::text,'other'),(b,'Synthetic quota B',b::text,'other');
  update public.business_subscriptions set commercial_access_enabled=true,is_permanent=true,subscription_status='active',
    paid_until=null,grace_until=null,restricted_until=null,archived_at=null where business_id in(a,b);
  insert into public.business_users(business_id,user_id,role,status,accepted_at) values(a,actor,'owner','active',now());
  insert into public.patients(id,business_id,owner_id,full_name) values(patient,a,actor,'Synthetic quota patient');
  perform set_config('request.jwt.claim.role','service_role',true);
  select * into f from public.begin_patient_radiograph_upload(actor,a,patient,gen_random_uuid(),'test.pdf','application/pdf',100,repeat('a',64));
  insert into quota_fixture values(a,b,gen_random_uuid(),actor,patient,f.radiograph_id,f.storage_path);
end $$;
select extensions.is((select max_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),100000000::bigint,'new clinic has an automatic 100 decimal MB maximum');
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),5000000::bigint,'a PDF URL reserves its full permitted five MB');
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select b from quota_fixture)),0::bigint,'individual maxima do not allocate the shared project budget');
select extensions.is((select max_bytes from public.clinical_storage_budget where singleton),700000000::bigint,'global capacity remains 700 decimal MB');
select extensions.ok((select business_id=(select a from quota_fixture) from public.clinical_upload_slots where file_id=(select file_id from quota_fixture)),'lease carries its constrained tenant identity');
select public.protect_clinical_upload_urls('patient-clinical-files',array[path],clock_timestamp()+interval '4 hours') from quota_fixture;
select extensions.ok((select expires_at>clock_timestamp()+interval '4 hours 14 minutes' from public.clinical_upload_slots where file_id=(select file_id from quota_fixture)),'observed provider expiration is backed with the full safety margin');
select extensions.is((select reserved_bytes from public.clinical_storage_budget where singleton),5000000::bigint,'extending a valid URL does not allocate its size twice');
select private.reserve_clinical_document(file_id) from quota_fixture;
select extensions.ok((select expires_at>clock_timestamp()+interval '4 hours 14 minutes' from public.clinical_upload_slots where file_id=(select file_id from quota_fixture)),'a later refresh never shortens protection for an earlier URL');
select extensions.throws_ok($q$select public.protect_clinical_upload_urls('patient-clinical-files',array[path,'unowned-path'],clock_timestamp()+interval '4 hours') from quota_fixture$q$,'P0001','CLINICAL_UPLOAD_PROTECTION_INVALID','URL protection cannot extend an unknown path');
select extensions.throws_ok($q$select public.set_business_clinical_storage_policy(actor,a,4999999,true) from quota_fixture$q$,'P0001','CLINICAL_STORAGE_COMMITTED','cannot reduce a clinic below an outstanding signed URL');
select extensions.throws_ok($q$update public.clinical_storage_budget set max_bytes=4999999 where singleton$q$,'P0001','CLINICAL_STORAGE_COMMITTED','cannot reduce the project below its outstanding URL');
select public.set_business_clinical_storage_policy(actor,a,5000000,true) from quota_fixture;
insert into storage.objects(bucket_id,name,metadata) select 'patient-clinical-files',path,'{"size":100,"mimetype":"application/pdf"}' from quota_fixture;
select extensions.is((select used_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),100::bigint,'actual bytes replace the pessimistic original reservation');
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),0::bigint,'completed object releases its backed pending space');
select extensions.is((select used_bytes from public.clinical_storage_budget where singleton),100::bigint,'global ledger observes the same real object');
select public.set_business_clinical_storage_policy(actor,a,100,true) from quota_fixture;
select extensions.throws_ok($q$delete from storage.objects where bucket_id='patient-clinical-files' and name=(select path from quota_fixture)$q$,'P0001','CLINICAL_STORAGE_QUOTA','deleting an object must still back its valid upload URL');
select extensions.is((select count(*) from storage.objects where name=(select path from quota_fixture)),1::bigint,'a failed quota transition never removes the stored object');
update public.clinical_upload_slots set expires_at=clock_timestamp()+interval '1 minute' where file_id=(select file_id from quota_fixture);
select private.reserve_clinical_document(file_id) from quota_fixture;
select extensions.ok((select expires_at>clock_timestamp()+interval '2 hours' from public.clinical_upload_slots where file_id=(select file_id from quota_fixture)),'refresh extends protection even when an original already exists');
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),0::bigint,'refresh does not charge a stored original twice');
select public.set_business_clinical_storage_policy(actor,a,6000000,false) from quota_fixture;
select extensions.is((select public.clinical_document_uploads_enabled(a) from quota_fixture),false,'effective module availability respects the clinic pause');
select extensions.throws_ok($q$select private.reserve_clinical_document(file_id) from quota_fixture$q$,'P0001','CLINICAL_DOCUMENTS_DISABLED','clinic availability prevents issuing new upload URLs');
select extensions.is((select count(*) from storage.objects where name=(select path from quota_fixture)),1::bigint,'disabling uploads preserves historical stored objects');
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(select actor::text from quota_fixture),true);
select extensions.throws_ok($q$select public.get_clinical_storage_budget(b) from quota_fixture$q$,'P0001','RADIOGRAPH_ACCESS_DENIED','a clinic owner cannot read another clinic quota');
select extensions.throws_ok($q$select public.save_public_practice_settings(a,'{"patient_documents_enabled":true}',(select updated_at from public.businesses where id=a)) from quota_fixture$q$,'P0001','CLINICAL_DOCUMENTS_DISABLED','activation cannot report success for a disabled account');
select extensions.is((select patient_documents_enabled from public.businesses where id=(select a from quota_fixture)),false,'rejected activation is atomic');
select set_config('request.jwt.claim.role','service_role',true);
select public.set_business_clinical_storage_policy(actor,a,6000000,true) from quota_fixture;
select set_config('request.jwt.claim.role','authenticated',true);
select public.save_public_practice_settings(a,'{"patient_documents_enabled":true}',(select updated_at from public.businesses where id=a)) from quota_fixture;
select public.save_public_practice_settings(a,'{"patient_documents_enabled":false}',(select updated_at from public.businesses where id=a)) from quota_fixture;
select public.save_public_practice_settings(a,'{"patient_documents_enabled":true}',(select updated_at from public.businesses where id=a)) from quota_fixture;
select extensions.is((select max_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),6000000::bigint,'deactivation and reactivation preserve the configured quota');
select set_config('request.jwt.claim.role','service_role',true);
select public.set_clinical_storage_defaults(actor,150000000,true) from quota_fixture;
select extensions.throws_ok($q$select public.set_clinical_storage_defaults(actor,0,true) from quota_fixture$q$,'23514',null,'no zero default can create an unusable activation');
select extensions.throws_ok($q$insert into public.clinical_upload_slots(bucket,path,file_id,business_id,expires_at,reserved_bytes) select 'patient-clinical-files','foreign-tenant-slot',file_id,b,now()+interval '1 hour',0 from quota_fixture$q$,'23503',null,'a lease cannot refer to a file in another clinic');
insert into public.businesses(id,name,slug,industry) select c,'Synthetic quota C',c::text,'other' from quota_fixture;
select extensions.is((select max_bytes from public.clinical_business_storage_budget where business_id=(select c from quota_fixture)),150000000::bigint,'new default applies automatically to subsequent clinics');
select extensions.is((select max_bytes from public.clinical_business_storage_budget where business_id=(select b from quota_fixture)),100000000::bigint,'default changes preserve previously assigned quotas');
select public.set_clinical_storage_defaults(actor,150000000,false) from quota_fixture;
select extensions.is((select public.clinical_document_uploads_enabled(a) from quota_fixture),false,'effective module availability also respects the global pause');
select extensions.throws_ok($q$select private.reserve_clinical_document(file_id) from quota_fixture$q$,'P0001','CLINICAL_DOCUMENTS_DISABLED','global operational availability is separate from the clinic setting');
select public.set_clinical_storage_defaults(actor,150000000,true) from quota_fixture;
select extensions.throws_ok($q$select public.reconcile_clinical_storage_budget(1)$q$,'P0001','CLINICAL_RECONCILIATION_LIMIT','bounded reconciliation fails explicitly rather than omitting clinics');
-- Deliberate counter drift models external modifications. Reconcile may repair
-- only derived counts, never file contents, metadata, patient rows or maxima.
update public.clinical_storage_budget set used_bytes=123,reserved_bytes=123;
update public.clinical_business_storage_budget set used_bytes=123,reserved_bytes=123 where business_id=(select a from quota_fixture);
select public.reconcile_clinical_storage_budget();
select extensions.is((select used_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),100::bigint,'reconciliation restores clinic usage from the complete object catalog');
select extensions.is((select reserved_bytes from public.clinical_storage_budget where singleton),0::bigint,'reconciliation repairs global reservation drift');
select extensions.is((select max_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),6000000::bigint,'reconciliation does not change a configured maximum');
select public.reconcile_clinical_storage_budget();
select extensions.is((select used_bytes from public.clinical_storage_budget where singleton),100::bigint,'reconciliation is repeatable without double counting');
select extensions.is((select count(*) from storage.objects where name=(select path from quota_fixture)),1::bigint,'reconciliation preserves the original object');
update public.clinical_upload_slots set expires_at=clock_timestamp()-interval '1 second' where file_id=(select file_id from quota_fixture);
select private.release_expired_clinical_reservations();
delete from storage.objects where name=(select path from quota_fixture);
select extensions.is((select used_bytes+reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),0::bigint,'expired URL requires no re-reservation after object deletion');
select private.reserve_clinical_document(file_id) from quota_fixture;
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),5000000::bigint,'an expired pending upload can renew with full backing');
select public.set_business_clinical_storage_policy(actor,a,20000000,true) from quota_fixture;
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),5000000::bigint,'increasing capacity preserves outstanding reservations');
select extensions.is((select sha256 from public.patient_radiographs where id=(select file_id from quota_fixture)),repeat('a',64),'increasing capacity preserves file identity');
select extensions.is((select count(*) from public.clinical_upload_slots where file_id=(select file_id from quota_fixture)),1::bigint,'increasing capacity does not duplicate or discard the pending lease');
update public.clinical_upload_slots set expires_at=clock_timestamp()-interval '1 second' where file_id=(select file_id from quota_fixture);
select private.release_expired_clinical_reservations();
select private.release_expired_clinical_reservations();
select extensions.is((select reserved_bytes from public.clinical_business_storage_budget where business_id=(select a from quota_fixture)),0::bigint,'expiration is repeatable and releases the clinic ledger once');
select extensions.ok(not has_function_privilege('authenticated','public.set_business_clinical_storage_policy(uuid,uuid,bigint,boolean,integer)','execute'),'ordinary users cannot administer individual quotas directly');
select extensions.ok(not has_function_privilege('anon','public.set_clinical_storage_defaults(uuid,bigint,boolean,integer)','execute'),'anonymous users cannot change operational defaults');
select extensions.ok(not has_function_privilege('authenticated','public.reconcile_clinical_storage_budget(integer)','execute'),'global reconciliation is backend-only');
select extensions.ok(not has_table_privilege('authenticated','public.clinical_business_storage_budget','update'),'direct table writes cannot bypass quota administration');
select extensions.ok(not has_function_privilege('service_role','private.lock_clinical_business_budget(uuid,boolean)','execute'),'internal helpers are not separately callable by the backend');
select extensions.ok(not has_function_privilege('authenticated','public.clinical_document_uploads_enabled(uuid)','execute'),'module availability is resolved only within the verified server context');
select extensions.throws_ok($q$select public.set_business_clinical_storage_policy(actor,a,100000000,true,1) from quota_fixture$q$,'P0001','CLINICAL_STORAGE_POLICY_CHANGED','stale quota settings cannot overwrite another administrator');
select extensions.throws_ok($q$select public.set_clinical_storage_defaults(actor,100000000,true,1) from quota_fixture$q$,'P0001','CLINICAL_STORAGE_POLICY_CHANGED','stale defaults cannot overwrite global operational availability');
select extensions.is((select policy_revision from public.clinical_business_storage_budget where business_id=(select b from quota_fixture)),1,'ordinary accounting leaves configuration revisions stable');
select * from extensions.finish();
rollback;
